// ============================================================================
// 4. PART DE FROMAGE COMTÉ AOP (Croûte Cendrée, Pâte Ivoire & Cristaux de Sel)
// ============================================================================
const ComteCheeseWedge: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  // Géométrie d'une part triangulaire de meule de fromage
  const wedgeShape = useMemo(() => {
    const shape = new THREE.Shape();
    shape.moveTo(0, 0);
    shape.lineTo(0.095, -0.042);
    shape.quadraticCurveTo(0.108, 0, 0.095, 0.042);
    shape.lineTo(0, 0);
    return shape;
  }, []);

  return (
    <group position={[0, 0, 0]}>
      {/* Pâte du Comté (Extrusion triangulaire) */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[-0.045, 0, 0]} castShadow>
        <extrudeGeometry args={[wedgeShape, { depth: 0.048, bevelEnabled: true, bevelThickness: 0.003, bevelSize: 0.003, bevelSegments: 3 }]} />
        <meshStandardMaterial color="#fef08a" roughness={0.55} metalness={0.06} />
      </mesh>

      {/* Croûte naturelle grise-ocre sur le talon arrondi */}
      <mesh position={[0.052, 0.024, 0]} rotation={[0, 0, 0]}>
        <cylinderGeometry args={[0.048, 0.048, 0.05, 16, 1, true, -Math.PI / 4, Math.PI / 2]} />
        <meshStandardMaterial color="#78716c" roughness={0.96} bumpScale={0.05} />
      </mesh>

      {/* Bandeau vert d'authenticité Comté AOP sur la croûte */}
      <mesh position={[0.053, 0.038, 0]} rotation={[0, 0, 0]}>
        <cylinderGeometry args={[0.0482, 0.0482, 0.012, 16, 1, true, -Math.PI / 4, Math.PI / 2]} />
        <meshStandardMaterial color="#15803d" roughness={0.7} />
      </mesh>

      {/* Micro-cristaux de tyrosine (sel croquant) sur la pâte */}
      {[
        [-0.01, 0.052, 0.01],
        [0.015, 0.052, -0.015],
        [0.03, 0.052, 0.018],
        [0.02, 0.052, 0.0]
      ].map((pos, cIdx) => (
        <mesh key={cIdx} position={pos as [number, number, number]}>
          <boxGeometry args={[0.002, 0.002, 0.002]} />
          <meshStandardMaterial color="#ffffff" roughness={0.2} metalness={0.2} />
        </mesh>
      ))}
    </group>
  );
};

