// ============================================================================
// 71. HORLOGE MURALE VINTAGE DE GARE (Cadran Émaillé & Trotteuse Rouge)
// ============================================================================
const VintageSchoolWallClock: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  const secondHandRef = useRef<THREE.Group>(null);
  useFrame(({ clock }) => {
    if (secondHandRef.current) {
      secondHandRef.current.rotation.z = -((clock.elapsedTime % 60) / 60) * Math.PI * 2;
    }
  });

  return (
    <group position={[0, 0, 0]} rotation={[0, 0, 0]}>
      {/* Boîtier circulaire profond en bakélite noire */}
      <mesh position={[0, 0, 0]} rotation={[Math.PI * 0.5, 0, 0]} castShadow>
        <cylinderGeometry args={[0.22, 0.22, 0.04, 32]} />
        <meshStandardMaterial color="#0f172a" roughness={0.6} />
      </mesh>

      {/* Lunette biseautée chromée */}
      <mesh position={[0, 0, 0.021]}>
        <torusGeometry args={[0.21, 0.012, 14, 32]} />
        <meshStandardMaterial color="#cbd5e1" metalness={0.92} roughness={0.15} />
      </mesh>

      {/* Cadran blanc émaillé crème avec index des heures */}
      <mesh position={[0, 0, 0.022]} rotation={[Math.PI * 0.5, 0, 0]}>
        <cylinderGeometry args={[0.20, 0.20, 0.002, 32]} />
        <meshStandardMaterial color="#fefce8" roughness={0.3} />
      </mesh>

      {/* 12 Index horaires noirs */}
      {Array.from({ length: 12 }).map((_, idx) => {
        const rad = (idx * Math.PI) / 6;
        const ix = Math.sin(rad) * 0.17;
        const iy = Math.cos(rad) * 0.17;
        return (
          <mesh
            key={`clock-index-${idx}`}
            position={[ix, iy, 0.024]}
            rotation={[0, 0, -rad]}
          >
            <boxGeometry args={[idx % 3 === 0 ? 0.012 : 0.006, 0.025, 0.002]} />
            <meshStandardMaterial color="#000000" roughness={0.3} />
          </mesh>
        );
      })}

      {/* Aiguille des heures (courte, noire) */}
      <mesh position={[0.035, 0.035, 0.026]} rotation={[0, 0, -Math.PI * 0.25]}>
        <boxGeometry args={[0.012, 0.09, 0.002]} />
        <meshStandardMaterial color="#000000" roughness={0.3} />
      </mesh>

      {/* Aiguille des minutes (longue, noire) */}
      <mesh position={[-0.02, 0.07, 0.028]} rotation={[0, 0, 0.3]}>
        <boxGeometry args={[0.008, 0.14, 0.002]} />
        <meshStandardMaterial color="#000000" roughness={0.3} />
      </mesh>

      {/* Trotteuse des secondes fine rouge vif animée */}
      <group ref={secondHandRef} position={[0, 0, 0.030]}>
        <mesh position={[0, 0.05, 0]}>
          <boxGeometry args={[0.003, 0.14, 0.002]} />
          <meshStandardMaterial color="#ef4444" roughness={0.2} />
        </mesh>
        <mesh position={[0, -0.02, 0]}>
          <cylinderGeometry args={[0.006, 0.006, 0.002, 12]} />
          <meshStandardMaterial color="#ef4444" roughness={0.2} />
        </mesh>
      </group>

      {/* Plot central du mécanisme */}
      <mesh position={[0, 0, 0.032]} rotation={[Math.PI * 0.5, 0, 0]}>
        <cylinderGeometry args={[0.012, 0.012, 0.004, 16]} />
        <meshStandardMaterial color="#000000" metalness={0.5} roughness={0.4} />
      </mesh>
    </group>
  );
};

