// ============================================================================
// 141. GLOBE TERRESTRE GÉOGRAPHIQUE VINTAGE (Méridien Laiton & Socle Noyer)
// ============================================================================
const VintageBrassDeskGlobe: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = ({ isHovered, isSelected }) => {
  const globeRef = useRef<THREE.Group>(null);
  useFrame((_, delta) => {
    if (globeRef.current) {
      const speed = isHovered || isSelected ? 1.2 : 0.3;
      globeRef.current.rotation.y += delta * speed;
    }
  });

  return (
    <group position={[0, 0, 0]}>
      {/* Socle circulaire en noyer massif tourné */}
      <mesh position={[0, 0.02, 0]} castShadow>
        <cylinderGeometry args={[0.08, 0.09, 0.04, 24]} />
        <meshStandardMaterial color="#582f0e" roughness={0.5} />
      </mesh>

      {/* Fût en laiton poli */}
      <mesh position={[0, 0.08, 0]} castShadow>
        <cylinderGeometry args={[0.012, 0.015, 0.08, 16]} />
        <meshStandardMaterial color="#d97706" metalness={0.9} roughness={0.2} />
      </mesh>

      {/* Demi-méridien circulaire gradué en laiton */}
      <mesh position={[0, 0.22, 0]} rotation={[0, 0, 0.4]}>
        <torusGeometry args={[0.13, 0.006, 12, 32, Math.PI]} />
        <meshStandardMaterial color="#d97706" metalness={0.9} roughness={0.2} />
      </mesh>

      {/* Sphère terrestre inclinée avec cartographie parcheminée animée */}
      <group position={[0, 0.22, 0]} rotation={[0.41, 0, 0]}>
        <group ref={globeRef}>
          <mesh castShadow>
            <sphereGeometry args={[0.11, 32, 32]} />
            <meshStandardMaterial color="#0284c7" roughness={0.4} />
          </mesh>
          {/* Continents dorés/verdoyants stylisés */}
          <mesh>
            <sphereGeometry args={[0.1105, 16, 16]} />
            <meshStandardMaterial color="#15803d" roughness={0.5} wireframe />
          </mesh>
        </group>
      </group>
    </group>
  );
};

