// ============================================================================
// 166. TORCHE MURALE EN FER FORGÉ & FLAMME VACILLANTE
// ============================================================================
const MedievalWallTorch: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  const flameRef = useRef<THREE.Mesh>(null);
  const torchLightRef = useRef<THREE.PointLight>(null);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime * 9;
    const flicker = 1.0 + Math.sin(t) * 0.15 + Math.cos(t * 2.4) * 0.1;
    if (flameRef.current) {
      flameRef.current.scale.set(0.9 + Math.sin(t * 1.5) * 0.12, flicker, 0.9 + Math.cos(t * 1.7) * 0.12);
    }
    if (torchLightRef.current) {
      torchLightRef.current.intensity = 1.6 * flicker;
    }
  });

  return (
    <group position={[0, 0, 0]}>
      {/* Platine murale en fer forgé martelé avec rivets */}
      <mesh position={[0, 1.20, -0.04]} castShadow>
        <boxGeometry args={[0.12, 0.32, 0.015]} />
        <meshStandardMaterial color="#1e293b" metalness={0.85} roughness={0.5} />
      </mesh>

      {/* Corbeau de soutien coudé en fer forgé */}
      <mesh position={[0, 1.15, 0.05]} rotation={[0.4, 0, 0]} castShadow>
        <boxGeometry args={[0.025, 0.18, 0.02]} />
        <meshStandardMaterial color="#0f172a" metalness={0.9} roughness={0.4} />
      </mesh>

      {/* Bague annulaire réceptacle du flambeau */}
      <mesh position={[0, 1.25, 0.12]} rotation={[Math.PI * 0.5, 0, 0]}>
        <torusGeometry args={[0.038, 0.006, 10, 24]} />
        <meshStandardMaterial color="#1e293b" metalness={0.85} roughness={0.4} />
      </mesh>

      {/* Flambeau en bois calciné ceinturé */}
      <mesh position={[0, 1.28, 0.12]} rotation={[0.1, 0, 0]} castShadow>
        <cylinderGeometry args={[0.032, 0.024, 0.28, 16]} />
        <meshStandardMaterial color="#451a03" roughness={0.9} />
      </mesh>

      {/* Tête de torche en étoupe et poix végétale calcinée */}
      <mesh position={[0, 1.44, 0.135]}>
        <cylinderGeometry args={[0.040, 0.034, 0.08, 16]} />
        <meshStandardMaterial color="#1c1917" roughness={0.95} />
      </mesh>

      {/* Flamme vive animée thermo-luminescente */}
      <mesh ref={flameRef} position={[0, 1.54, 0.14]}>
        <coneGeometry args={[0.035, 0.14, 16]} />
        <meshStandardMaterial
          color="#fef08a"
          emissive="#f97316"
          emissiveIntensity={2.4}
          roughness={0.1}
          transparent
          opacity={0.92}
        />
      </mesh>

      <pointLight ref={torchLightRef} position={[0, 1.58, 0.16]} color="#f97316" intensity={1.6} distance={4.0} />
    </group>
  );
};

// ============================================================================
// 167. BRASERO CIRCULAIRE EN FONTE FORGÉE & CHARBONS ARDENTS
// ============================================================================
const CastIronBrazier: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  const embersRef = useRef<THREE.Mesh>(null);
  const brazierLightRef = useRef<THREE.PointLight>(null);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime * 7;
    const flicker = 1.0 + Math.sin(t) * 0.16 + Math.cos(t * 1.9) * 0.1;
    if (embersRef.current) {
      (embersRef.current.material as THREE.MeshStandardMaterial).emissiveIntensity = 1.7 * flicker;
    }
    if (brazierLightRef.current) {
      brazierLightRef.current.intensity = 1.8 * flicker;
    }
  });

  return (
    <group position={[0, 0, 0]}>
      {/* 3 Pieds galbés en fer forgé forgés au sol */}
      {Array.from({ length: 3 }).map((_, idx) => {
        const rad = (idx * Math.PI * 2) / 3;
        const px = Math.sin(rad) * 0.22;
        const pz = Math.cos(rad) * 0.22;
        return (
          <mesh key={`brazier-leg-${idx}`} position={[px, 0.18, pz]} rotation={[0.2, -rad, 0]} castShadow>
            <cylinderGeometry args={[0.015, 0.018, 0.38, 12]} />
            <meshStandardMaterial color="#0f172a" metalness={0.8} roughness={0.5} />
          </mesh>
        );
      })}

      {/* Anneau support inférieur circulaire */}
      <mesh position={[0, 0.12, 0]}>
        <torusGeometry args={[0.18, 0.012, 10, 24]} />
        <meshStandardMaterial color="#1e293b" metalness={0.8} roughness={0.4} />
      </mesh>

      {/* Vasque hémisphérique évasée en fonte */}
      <mesh position={[0, 0.38, 0]} castShadow>
        <sphereGeometry args={[0.28, 24, 16, 0, Math.PI * 2, 0, Math.PI * 0.55]} />
        <meshStandardMaterial color="#1e293b" metalness={0.7} roughness={0.6} side={THREE.DoubleSide} />
      </mesh>

      {/* Rebord forgé épaissi de la vasque */}
      <mesh position={[0, 0.44, 0]} rotation={[Math.PI * 0.5, 0, 0]}>
        <torusGeometry args={[0.28, 0.014, 12, 32]} />
        <meshStandardMaterial color="#0f172a" metalness={0.85} roughness={0.4} />
      </mesh>

      {/* Lit de braises incandescentes animées */}
      <mesh ref={embersRef} position={[0, 0.38, 0]}>
        <cylinderGeometry args={[0.24, 0.18, 0.10, 24]} />
        <meshStandardMaterial
          color="#ea580c"
          emissive="#f97316"
          emissiveIntensity={1.8}
          roughness={0.5}
        />
      </mesh>

      {/* Morceaux de charbon ardents en surface */}
      {[-0.08, 0, 0.08].map((cx, cIdx) =>
        [-0.06, 0.06].map((cz, zIdx) => (
          <mesh key={`coal-${cIdx}-${zIdx}`} position={[cx, 0.44, cz]}>
            <dodecahedronGeometry args={[0.035, 0]} />
            <meshStandardMaterial color="#292524" roughness={0.9} />
          </mesh>
        ))
      )}

      <pointLight ref={brazierLightRef} position={[0, 0.55, 0]} color="#ea580c" intensity={1.8} distance={4.0} />
    </group>
  );
};

// ============================================================================
// 168. CRISTAL MAGIQUE PRISMATIQUE LUMINESCENT & AURA
// ============================================================================
const PrismaticMagicCrystal: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  const crystalGroupRef = useRef<THREE.Group>(null);
  const crystalLightRef = useRef<THREE.PointLight>(null);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime;
    if (crystalGroupRef.current) {
      crystalGroupRef.current.position.y = 0.24 + Math.sin(t * 2) * 0.025;
      crystalGroupRef.current.rotation.y = t * 0.5;
    }
    if (crystalLightRef.current) {
      crystalLightRef.current.intensity = 1.4 + Math.sin(t * 3) * 0.4;
    }
  });

  return (
    <group position={[0, 0, 0]}>
      {/* Socle géologique naturel en basalte texturé */}
      <mesh position={[0, 0.06, 0]} castShadow>
        <cylinderGeometry args={[0.18, 0.22, 0.12, 7]} />
        <meshStandardMaterial color="#1e293b" roughness={0.9} />
      </mesh>

      {/* Grappe de cristaux lévitants magiques avec rotation continue */}
      <group ref={crystalGroupRef} position={[0, 0.24, 0]}>
        {/* Prisme central majeur */}
        <mesh castShadow>
          <cylinderGeometry args={[0.06, 0.08, 0.28, 6]} />
          <meshPhysicalMaterial
            color="#c084fc"
            emissive="#a855f7"
            emissiveIntensity={1.5}
            roughness={0.06}
            transmission={0.88}
            ior={1.65}
            clearcoat={1.0}
          />
        </mesh>
        {/* Pointe pyramidale acérée du prisme central */}
        <mesh position={[0, 0.18, 0]}>
          <coneGeometry args={[0.06, 0.08, 6]} />
          <meshPhysicalMaterial
            color="#e879f9"
            emissive="#c084fc"
            emissiveIntensity={1.6}
            roughness={0.06}
            transmission={0.88}
            ior={1.65}
            clearcoat={1.0}
          />
        </mesh>

        {/* 3 Petits cristaux latéraux satellites inclinés */}
        {Array.from({ length: 3 }).map((_, idx) => {
          const rad = (idx * Math.PI * 2) / 3;
          const sx = Math.sin(rad) * 0.07;
          const sz = Math.cos(rad) * 0.07;
          return (
            <mesh key={`sub-crystal-${idx}`} position={[sx, -0.04, sz]} rotation={[0.3, -rad, 0.2]}>
              <cylinderGeometry args={[0.025, 0.035, 0.16, 6]} />
              <meshPhysicalMaterial
                color="#38bdf8"
                emissive="#00e5ff"
                emissiveIntensity={1.3}
                roughness={0.08}
                transmission={0.85}
                ior={1.6}
                clearcoat={1.0}
              />
            </mesh>
          );
        })}
      </group>

      <pointLight ref={crystalLightRef} position={[0, 0.30, 0]} color="#c084fc" intensity={1.4} distance={2.5} />
    </group>
  );
};

