// ============================================================================
// 214. FLÈCHE 3D DIRECTIONNELLE HOLOGRAPHIQUE LÉVITANTE & PULSANTE
// ============================================================================
const HolographicDirectionalArrow: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  const arrowGroupRef = useRef<THREE.Group>(null);
  useFrame(({ clock }) => {
    if (arrowGroupRef.current) {
      arrowGroupRef.current.position.y = 0.45 + Math.sin(clock.getElapsedTime() * 3.5) * 0.05;
      arrowGroupRef.current.rotation.y = clock.getElapsedTime() * 0.8;
    }
  });

  return (
    <group ref={arrowGroupRef} position={[0, 0.45, 0]}>
      {/* Tête de flèche volumétrique triangulaire */}
      <mesh position={[0, 0.12, 0]} rotation={[0, 0, 0]}>
        <coneGeometry args={[0.12, 0.22, 16]} />
        <meshStandardMaterial
          color="#06b6d4"
          emissive="#06b6d4"
          emissiveIntensity={0.8}
          roughness={0.2}
          transparent
          opacity={0.88}
        />
      </mesh>
      {/* Corps tubulaire de la flèche */}
      <mesh position={[0, -0.06, 0]}>
        <cylinderGeometry args={[0.045, 0.045, 0.18, 16]} />
        <meshStandardMaterial
          color="#0891b2"
          emissive="#0891b2"
          emissiveIntensity={0.6}
          roughness={0.2}
          transparent
          opacity={0.85}
        />
      </mesh>
      {/* Halo lumineux ponctuel rayonnant */}
      <pointLight color="#06b6d4" intensity={2} distance={1.5} />
    </group>
  );
};

