// ============================================================================
// 341. PRISME OPTIQUE TRIANGULAIRE EN CRISTAL & SPECTRE
// ============================================================================
const SpectralOpticalTriangularPrism: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  const spectralRef = useRef<THREE.PointLight>(null);
  useFrame(({ clock }) => {
    if (spectralRef.current) {
      spectralRef.current.intensity = 0.8 + Math.sin(clock.elapsedTime * 3) * 0.25;
    }
  });

  return (
    <group position={[0, 0.06, 0]} rotation={[0, 0.4, 0]}>
      {/* Prisme optique triangulaire en verre pur borosilicate */}
      <mesh castShadow>
        <cylinderGeometry args={[0.07, 0.07, 0.12, 3]} />
        <meshPhysicalMaterial
          color="#ffffff"
          transmission={0.98}
          roughness={0.03}
          ior={1.62}
          clearcoat={1.0}
        />
      </mesh>
      {/* Faisceau de projection spectrale de diffraction arc-en-ciel */}
      <mesh position={[0.06, 0, 0.06]} rotation={[0, 0.8, 0]}>
        <planeGeometry args={[0.08, 0.06]} />
        <meshBasicMaterial color="#38bdf8" transparent opacity={0.6} side={THREE.DoubleSide} />
      </mesh>
      <pointLight ref={spectralRef} position={[0.06, 0.02, 0.06]} color="#a855f7" intensity={0.8} distance={1.2} />
    </group>
  );
};

