const QuarterFractionsEducationalDisc: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  return (
    <group position={[0, 0.02, 0]} rotation={[-Math.PI / 2, 0, 0]}>
      {/* Plateau support circulaire en bois */}
      <mesh position={[0, 0, -0.008]} castShadow>
        <cylinderGeometry args={[0.11, 0.11, 0.012, 32]} />
        <meshStandardMaterial color="#d4a373" roughness={0.6} />
      </mesh>
      {/* 4 Secteurs de quart (1/4) colorés distincts */}
      {[
        [0, '#ef4444'],
        [Math.PI / 2, '#3b82f6'],
        [Math.PI, '#10b981'],
        [(3 * Math.PI) / 2, '#facc15'],
      ].map(([ang, col], qi) => (
        <group key={qi} position={[qi === 0 ? 0.01 : 0, qi === 0 ? 0.01 : 0, qi === 0 ? 0.005 : 0]}>
          <mesh rotation={[0, 0, ang as number]} castShadow>
            <cylinderGeometry args={[0.095, 0.095, 0.01, 16, 1, false, 0, Math.PI / 2]} />
            <meshPhysicalMaterial color={col as string} roughness={0.3} clearcoat={0.7} />
          </mesh>
        </group>
      ))}
    </group>
  );
};

