// ============================================================================
// 345. RÉGLETTES DE CUISENAIRE / BARRES DE NUMÉRATION EN BOIS
// ============================================================================
const CuisenaireNumberBarsSet: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  // 10 réglettes aux teintes normalisées Cuisenaire : 1cm à 10cm
  const bars = [
    { len: 0.018, color: '#f8fafc' }, // 1: Blanc
    { len: 0.036, color: '#dc2626' }, // 2: Rouge
    { len: 0.054, color: '#86efac' }, // 3: Vert clair
    { len: 0.072, color: '#9333ea' }, // 4: Pourpre/Carmine
    { len: 0.090, color: '#facc15' }, // 5: Jaune
    { len: 0.108, color: '#15803d' }, // 6: Vert foncé
    { len: 0.126, color: '#0f172a' }, // 7: Noir
    { len: 0.144, color: '#78350f' }, // 8: Brun
    { len: 0.162, color: '#2563eb' }, // 9: Bleu
    { len: 0.180, color: '#ea580c' }, // 10: Orange
  ];

  return (
    <group position={[0, 0.015, 0]}>
      {/* Plumier / plateau en hêtre clair rainuré */}
      <mesh position={[0, 0, 0]} castShadow>
        <boxGeometry args={[0.22, 0.016, 0.22]} />
        <meshStandardMaterial color="#d4a373" roughness={0.65} />
      </mesh>
      {/* 10 réglettes alignées en escalier régulier */}
      {bars.map((bar, idx) => (
        <mesh
          key={idx}
          position={[-0.09 + idx * 0.02, 0.016, -0.09 + bar.len / 2]}
          castShadow
        >
          <boxGeometry args={[0.016, 0.016, bar.len]} />
          <meshPhysicalMaterial color={bar.color} roughness={0.4} clearcoat={0.3} />
        </mesh>
      ))}
    </group>
  );
};

// ============================================================================
// 346. ESCALIER SENSORIEL DE CUBES MONTESSORI (TOUR ROSE)
// ============================================================================
const MontessoriCubeStaircase: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  // 10 cubes gradués de 1cm à 10cm en progression volumique
  const cubes = Array.from({ length: 10 }).map((_, i) => ({
    size: 0.012 + i * 0.009,
    pos: -0.12 + i * 0.026,
  }));

  return (
    <group position={[0, 0.01, 0]}>
      {/* Plateau de présentation sobre */}
      <mesh position={[0, 0.005, 0]} castShadow>
        <boxGeometry args={[0.3, 0.01, 0.15]} />
        <meshStandardMaterial color="#f1f5f9" roughness={0.5} />
      </mesh>
      {/* 10 cubes disposés en cascade d'escalier croissant */}
      {cubes.map((c, idx) => (
        <mesh key={idx} position={[c.pos, 0.01 + c.size / 2, 0]} castShadow>
          <boxGeometry args={[c.size, c.size, c.size]} />
          <meshPhysicalMaterial
            color="#f472b6"
            roughness={0.25}
            clearcoat={0.65}
          />
        </mesh>
      ))}
    </group>
  );
};

