// ============================================================================
// 402. BÂTON DE MAGE RUNIQUE EN BOIS D'IF & CRISTAL PHOSPHORESCENT
// ============================================================================
const ArcaneRunedWizardStaff: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  const crystalLightRef = useRef<THREE.PointLight>(null);
  const crystalGroupRef = useRef<THREE.Group>(null);

  useFrame(({ clock }) => {
    const t = clock.elapsedTime;
    if (crystalGroupRef.current) {
      crystalGroupRef.current.position.y = 0.44 + Math.sin(t * 2) * 0.015;
      crystalGroupRef.current.rotation.y = t * 0.8;
    }
    if (crystalLightRef.current) {
      crystalLightRef.current.intensity = 1.2 + Math.sin(t * 3.5) * 0.4;
    }
  });

  return (
    <group position={[0, 0.35, 0]} rotation={[0, 0, 0.08]}>
      {/* Hampe torsadée sculptée en vieux bois d'if avec veinage noueux */}
      <mesh position={[0, -0.05, 0]} castShadow>
        <cylinderGeometry args={[0.018, 0.022, 0.80, 16]} />
        <meshStandardMaterial color="#451a03" roughness={0.75} />
      </mesh>

      {/* Griffes supérieures en bois formant réceptacle */}
      <group position={[0, 0.38, 0]}>
        {[0, (2 * Math.PI) / 3, (4 * Math.PI) / 3].map((ang, gi) => (
          <mesh
            key={gi}
            position={[Math.cos(ang) * 0.022, 0.02, Math.sin(ang) * 0.022]}
            rotation={[0.3, -ang, 0]}
            castShadow
          >
            <cylinderGeometry args={[0.004, 0.008, 0.07, 8]} />
            <meshStandardMaterial color="#5c3a21" roughness={0.7} />
          </mesh>
        ))}
      </group>

      {/* Cristal arcanique octogonal flottant et pulsant */}
      <group ref={crystalGroupRef}>
        <mesh castShadow>
          <octahedronGeometry args={[0.032]} />
          <meshPhysicalMaterial
            color="#38bdf8"
            emissive="#0284c7"
            emissiveIntensity={0.8}
            transmission={0.8}
            roughness={0.05}
            clearcoat={1.0}
          />
        </mesh>
        <pointLight ref={crystalLightRef} color="#38bdf8" intensity={1.2} distance={1.8} />
      </group>
    </group>
  );
};

