        <mesh castShadow>
          <boxGeometry args={[0.12, 0.08, 0.10]} />
          <meshPhysicalMaterial color="#334155" metalness={0.7} roughness={0.35} />
        </mesh>

        {/* Dôme LIDAR rotatif supérieur noir lustré */}
        <mesh position={[0, 0.055, 0]} castShadow>
          <cylinderGeometry args={[0.038, 0.042, 0.03, 20]} />
          <meshPhysicalMaterial color="#020617" roughness={0.1} clearcoat={1.0} />
        </mesh>

        {/* Deux optiques stéréoscopiques frontales bleues */}
