// ============================================================================
// 464. BALLE SENSORIELLE À PICOTS SOUPLES EN SILICONE PASTEL
// ============================================================================
const SensoryTexturedNubBall: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  const ballRef = useRef<THREE.Group>(null);
  useFrame(({ clock }) => {
    if (ballRef.current) {
      const squish = 1.0 + Math.sin(clock.elapsedTime * 3) * 0.04;
      ballRef.current.scale.set(squish, 2.0 - squish, squish);
    }
  });

  return (
    <group ref={ballRef} position={[0, 0.08, 0]}>
      {/* Sphère centrale en silicone souple turquoise menthe */}
      <mesh castShadow>
        <sphereGeometry args={[0.07, 24, 20]} />
        <meshPhysicalMaterial
          color="#2dd4bf"
          roughness={0.4}
          clearcoat={0.3}
          clearcoatRoughness={0.2}
        />
      </mesh>

      {/* 24 Picots souples coniques répartis sur la circonférence */}
      {Array.from({ length: 24 }).map((_, i) => {
        const phi = Math.acos(-1 + (2 * i) / 24);
        const theta = Math.sqrt(24 * Math.PI) * phi;
        const x = Math.sin(phi) * Math.cos(theta);
        const y = Math.cos(phi);
        const z = Math.sin(phi) * Math.sin(theta);
        return (
          <group key={i} position={[x * 0.07, y * 0.07, z * 0.07]}>
            <mesh position={[x * 0.012, y * 0.012, z * 0.012]} castShadow>
              <sphereGeometry args={[0.012, 10, 8]} />
              <meshStandardMaterial color="#5eead4" roughness={0.5} />
            </mesh>
          </group>
        );
      })}
    </group>
  );
};

