// ============================================================================
// 500. PORTE VITRÉE BATTANTE EN ALUMINIUM BROSSÉ & DOUBLE VITRAGE (wp-porte-vitree)
// ============================================================================
const AluminumFramedGlassPivotDoor: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = ({ isSelected, isHovered }) => {
  const doorRef = useRef<THREE.Group>(null);
  useFrame((state) => {
    if (doorRef.current && (isHovered || isSelected)) {
      doorRef.current.rotation.y = Math.sin(state.clock.elapsedTime * 2) * 0.15 - 0.2;
    } else if (doorRef.current) {
      doorRef.current.rotation.y = 0;
    }
  });

  return (
    <group position={[0, 1.05, 0]}>
      {/* Dormant fixe extérieur en profilé aluminium extrudé gris anthracite */}
      <mesh position={[0, 0, 0]} castShadow>
        <boxGeometry args={[0.96, 2.12, 0.10]} />
        <meshStandardMaterial color="#1e293b" metalness={0.8} roughness={0.3} />
      </mesh>
      {/* Évidement de l'ouverture du bâti */}
      <mesh position={[0, 0, 0]}>
        <boxGeometry args={[0.84, 2.02, 0.12]} />
        <meshStandardMaterial color="#0f172a" roughness={0.9} />
      </mesh>

      {/* Vantail mobile pivotant sur axe déporté */}
      <group ref={doorRef} position={[-0.42, 0, 0]}>
        <group position={[0.42, 0, 0]}>
          {/* Cadre fin du vantail en aluminium anodisé */}
          <mesh castShadow>
            <boxGeometry args={[0.82, 2.00, 0.045]} />
            <meshStandardMaterial color="#334155" metalness={0.85} roughness={0.25} />
          </mesh>

          {/* Grand vitrage thermique transparent physique */}
          <mesh>
            <boxGeometry args={[0.72, 1.90, 0.018]} />
            <meshPhysicalMaterial
              color="#f0fdf4"
              transmission={0.94}
              opacity={1}
              transparent={true}
              roughness={0.03}
              ior={1.52}
              clearcoat={1.0}
            />
          </mesh>

          {/* Grande poignée bâton de tirage verticale toute hauteur en inox brossé */}
          <group position={[0.32, 0, 0.04]}>
            <mesh castShadow>
              <cylinderGeometry args={[0.016, 0.016, 0.90, 16]} />
              <meshStandardMaterial color="#cbd5e1" metalness={0.95} roughness={0.15} />
            </mesh>
            {/* 2 Entretoises de fixation de la poignée */}
            {[-0.38, 0.38].map((ey, ei) => (
              <mesh key={ei} position={[0, ey, -0.02]} rotation={[Math.PI / 2, 0, 0]}>
                <cylinderGeometry args={[0.012, 0.012, 0.04, 12]} />
                <meshStandardMaterial color="#94a3b8" metalness={0.9} roughness={0.2} />
              </mesh>
            ))}
          </group>

          {/* Pivot de rotation dissimulé sol/plafond */}
          {[-0.99, 0.99].map((py, pi) => (
            <mesh key={pi} position={[-0.36, py, 0]}>
              <cylinderGeometry args={[0.015, 0.015, 0.03, 16]} />
              <meshStandardMaterial color="#64748b" metalness={0.9} />
            </mesh>
          ))}
        </group>
      </group>
    </group>
  );
};

