// ============================================================================
// 505. ROBOT QUADRUPÈDE D'EXPLORATION & TOURELLE LIDAR (wp-robot-quadrupede)
// ============================================================================
const QuadrupedInspectionScoutRobot: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = ({ isSelected, isHovered }) => {
  const robotRef = useRef<THREE.Group>(null);
  const lidarRef = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (robotRef.current) {
      robotRef.current.position.y = 0.35 + Math.sin(state.clock.elapsedTime * 2.5) * 0.012;
    }
    if (lidarRef.current) {
      lidarRef.current.rotation.y = state.clock.elapsedTime * 4;
    }
  });

  return (
    <group ref={robotRef} position={[0, 0.35, 0]}>
      {/* Châssis central profilé en polymère technique jaune et fibre de carbone */}
      <mesh castShadow receiveShadow>
        <boxGeometry args={[0.32, 0.18, 0.62]} />
        <meshPhysicalMaterial
          color={isSelected ? '#fde047' : isHovered ? '#fef08a' : '#eab308'}
          roughness={0.3}
          metalness={0.2}
          clearcoat={0.6}
        />
      </mesh>
      {/* Plaque ventrale de protection en composite carbone noir */}
      <mesh position={[0, -0.095, 0]}>
        <boxGeometry args={[0.28, 0.02, 0.58]} />
        <meshStandardMaterial color="#1e293b" roughness={0.7} metalness={0.5} />
      </mesh>
      {/* Poignées tubulaires supérieures de portage */}
      {[-0.14, 0.14].map((hx, hi) => (
        <mesh key={hi} position={[hx, 0.10, 0]}>
          <boxGeometry args={[0.02, 0.03, 0.45]} />
          <meshStandardMaterial color="#0f172a" metalness={0.8} roughness={0.3} />
        </mesh>
      ))}

      {/* Tourelle supérieure de perception avec capteur LIDAR rotatif et caméra stéréo */}
      <group position={[0, 0.13, 0.18]}>
        <mesh castShadow>
          <cylinderGeometry args={[0.065, 0.075, 0.06, 24]} />
          <meshStandardMaterial color="#0f172a" metalness={0.8} roughness={0.3} />
        </mesh>
        {/* Disque LIDAR rotatif ultra-rapide */}
        <mesh ref={lidarRef} position={[0, 0.045, 0]}>
          <cylinderGeometry args={[0.05, 0.05, 0.025, 20]} />
          <meshStandardMaterial color="#0284c7" emissive="#38bdf8" emissiveIntensity={0.6} />
        </mesh>
        {/* Double optique stéréoscopique avant */}
        {[-0.03, 0.03].map((cx, ci) => (
          <mesh key={ci} position={[cx, -0.01, 0.065]} rotation={[Math.PI / 2, 0, 0]}>
            <cylinderGeometry args={[0.012, 0.012, 0.015, 16]} />
            <meshStandardMaterial color="#38bdf8" roughness={0.1} />
          </mesh>
        ))}
      </group>

      {/* 4 Membres articulés à deux segments (fémur et tibia) avec rotules */}
      {[[-0.20, -0.22], [0.20, -0.22], [-0.20, 0.22], [0.20, 0.22]].map(([lx, lz], li) => {
        const isFront = lz > 0;
        return (
          <group key={li} position={[lx, -0.02, lz]}>
            {/* Épaule / servomoteur rotatif */}
            <mesh castShadow>
              <sphereGeometry args={[0.042, 16, 16]} />
              <meshStandardMaterial color="#0f172a" metalness={0.9} roughness={0.2} />
            </mesh>
            {/* Segment supérieur (fémur) incliné vers l'extérieur */}
            <mesh position={[lx > 0 ? 0.04 : -0.04, -0.10, isFront ? 0.04 : -0.04]} rotation={[isFront ? 0.35 : -0.35, 0, lx > 0 ? -0.2 : 0.2]} castShadow>
              <cylinderGeometry args={[0.018, 0.014, 0.22, 12]} />
              <meshStandardMaterial color="#334155" metalness={0.8} roughness={0.3} />
            </mesh>
            {/* Genou / articulation intermédiaire */}
            <mesh position={[lx > 0 ? 0.08 : -0.08, -0.20, isFront ? 0.08 : -0.08]}>
              <sphereGeometry args={[0.028, 12, 12]} />
              <meshStandardMaterial color="#0f172a" metalness={0.9} />
            </mesh>
            {/* Segment inférieur (tibia) incliné vers le sol */}
            <mesh position={[lx > 0 ? 0.06 : -0.06, -0.29, isFront ? 0.04 : -0.04]} rotation={[isFront ? -0.4 : 0.4, 0, lx > 0 ? 0.1 : -0.1]} castShadow>
              <cylinderGeometry args={[0.012, 0.010, 0.20, 10]} />
              <meshStandardMaterial color="#1e293b" metalness={0.7} />
            </mesh>
            {/* Patin sphérique en caoutchouc antidérapant au sol */}
            <mesh position={[lx > 0 ? 0.04 : -0.04, -0.37, 0]}>
              <sphereGeometry args={[0.024, 14, 14]} />
              <meshStandardMaterial color="#020617" roughness={0.95} />
            </mesh>
          </group>
        );
      })}
    </group>
  );
};

