// ============================================================================
// 512. COFFRET D'EXPRESSION EN MARQUETERIE & JETONS GRAVÉS (wp-coffret-d-expression)
// ============================================================================
const InlaidMarquetryExpressionGiftBox: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = ({ isSelected, isHovered }) => {
  const lidRef = useRef<THREE.Group>(null);
  useFrame((state) => {
    if (lidRef.current && (isHovered || isSelected)) {
      lidRef.current.rotation.x = -0.45 + Math.sin(state.clock.elapsedTime * 2) * 0.08;
    } else if (lidRef.current) {
      lidRef.current.rotation.x = -0.45;
    }
  });

  return (
    <group position={[0, 0.1, 0]}>
      {/* Boîtier inférieur en palissandre avec marqueterie d'ébène et de buis */}
      <mesh position={[0, 0, 0]} castShadow receiveShadow>
        <boxGeometry args={[0.32, 0.12, 0.24]} />
        <meshPhysicalMaterial
          color="#581c87"
          roughness={0.3}
          metalness={0.1}
          clearcoat={0.7}
          clearcoatRoughness={0.15}
        />
      </mesh>
      {/* Filets de marqueterie dorés en buis sur le pourtour */}
      <mesh position={[0, 0, 0]}>
        <boxGeometry args={[0.324, 0.015, 0.244]} />
        <meshStandardMaterial color="#fef08a" metalness={0.7} roughness={0.3} />
      </mesh>

      {/* Intérieur capitonné de velours pourpre */}
      <mesh position={[0, 0.05, 0]}>
        <boxGeometry args={[0.29, 0.02, 0.21]} />
        <meshStandardMaterial color="#701a75" roughness={0.95} />
      </mesh>

      {/* Jetons et cartes d'expression disposés à l'intérieur */}
      {[-0.07, 0, 0.07].map((tx, ti) => (
        <group key={ti} position={[tx, 0.065, 0]}>
          <mesh castShadow>
            <cylinderGeometry args={[0.028, 0.028, 0.008, 16]} />
            <meshStandardMaterial color="#fbbf24" metalness={0.8} roughness={0.25} />
          </mesh>
        </group>
      ))}

      {/* Couvercle articulé avec fermoir à bascule en laiton */}
      <group ref={lidRef} position={[0, 0.06, -0.12]}>
        <mesh position={[0, 0.015, 0.12]} castShadow>
          <boxGeometry args={[0.325, 0.03, 0.245]} />
          <meshPhysicalMaterial
            color="#581c87"
            roughness={0.3}
            metalness={0.1}
            clearcoat={0.7}
          />
        </mesh>
        {/* Rosace centrale marquetée sur le couvercle */}
        <mesh position={[0, 0.032, 0.12]}>
          <cylinderGeometry args={[0.05, 0.05, 0.002, 24]} />
          <meshStandardMaterial color="#fef08a" metalness={0.7} roughness={0.3} />
        </mesh>
        {/* Fermoir avant en laiton doré */}
        <mesh position={[0, -0.01, 0.245]}>
          <boxGeometry args={[0.03, 0.04, 0.01]} />
          <meshStandardMaterial color="#d97706" metalness={0.9} roughness={0.2} />
        </mesh>
      </group>
    </group>
  );
};

