// ============================================================================
// 530. ARTICHAUT CAMUS DE BRETAGNE AUX BRACTÉES CHARNUES (wp-artichaut)
// ============================================================================
const BretonCamusGlobeArtichoke: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = () => {
  return (
    <group position={[0, 0.09, 0]}>
      {/* Cœur et capitule floral sphérique */}
      <mesh position={[0, 0.04, 0]} castShadow>
        <sphereGeometry args={[0.07, 16, 16]} />
        <meshStandardMaterial color="#166534" roughness={0.6} />
      </mesh>

      {/* 4 Rangs étagés de bractées charnues imbriquées en écailles */}
      {[0, 1, 2, 3].map((ringIdx) => {
        const ringY = -0.01 + ringIdx * 0.03;
        const count = 7 + ringIdx * 2;
        const radius = 0.065 - ringIdx * 0.008;
        return (
          <group key={ringIdx} position={[0, ringY, 0]}>
            {Array.from({ length: count }).map((_, bi) => {
              const angle = (bi * Math.PI * 2) / count + (ringIdx * 0.3);
              return (
                <mesh
                  key={bi}
                  position={[Math.cos(angle) * radius, 0, Math.sin(angle) * radius]}
                  rotation={[0.3, -angle, 0]}
                  castShadow
                >
                  <boxGeometry args={[0.032, 0.038, 0.008]} />
                  <meshPhysicalMaterial
                    color={ringIdx === 3 ? '#581c87' : '#15803d'}
                    roughness={0.45}
                    clearcoat={0.3}
                  />
                </mesh>
              );
            })}
          </group>
        );
      })}

      {/* Pédoncule / tige cylindrique épaisse coupée nette */}
      <mesh position={[0, -0.06, 0]} castShadow>
        <cylinderGeometry args={[0.014, 0.016, 0.08, 14]} />
        <meshStandardMaterial color="#166534" roughness={0.7} />
      </mesh>
    </group>
  );
};

