// ============================================================================
// MODÈLES CERTIFIÉS : SHOWROOM LUXE, PÂTISSERIE, SUPERCAR & ESPACE VICTORIA VR
// ============================================================================

// Cache pour les textures procédurales haute fidélité (Maroquinerie, Pâtisserie, Hypercar, Carbone, Marbre)
const lvTextureCache: {
  monogram: THREE.CanvasTexture | null;
  taurillon: THREE.CanvasTexture | null;
  marble: THREE.CanvasTexture | null;
  bakedCookie: THREE.CanvasTexture | null;
  carbonFiber: THREE.CanvasTexture | null;
  parchmentPaper: THREE.CanvasTexture | null;
} = {
  monogram: null,
  taurillon: null,
  marble: null,
  bakedCookie: null,
  carbonFiber: null,
  parchmentPaper: null
};

function getLouisVuittonMonogramTexture(): THREE.CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  if (lvTextureCache.monogram) return lvTextureCache.monogram;

  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // 1. Fond riche en toile enduite chocolat profond Louis Vuitton
  ctx.fillStyle = '#26180f';
  ctx.fillRect(0, 0, 512, 512);

  // 2. Micro-grain de toile enduite imperméable
  const imgData = ctx.getImageData(0, 0, 512, 512);
  for (let i = 0; i < imgData.data.length; i += 4) {
    const noise = (Math.random() - 0.5) * 16;
    imgData.data[i] = Math.max(0, Math.min(255, imgData.data[i] + noise));
    imgData.data[i + 1] = Math.max(0, Math.min(255, imgData.data[i + 1] + noise * 0.7));
    imgData.data[i + 2] = Math.max(0, Math.min(255, imgData.data[i + 2] + noise * 0.45));
  }
  ctx.putImageData(imgData, 0, 0);

  // 3. Dessin des 4 motifs emblématiques de la Maison Louis Vuitton en ocre doré
  const goldColor = '#caa066';
  const goldOutline = '#dcaf6d';
  const darkBrown = '#26180f';
  const S = 128; // Taille de cellule de la grille

  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 4; col++) {
      const cx = col * S + S / 2;
      const cy = row * S + S / 2;
      const type = (col + row * 3) % 4;

      if (type === 0) {
        // Motif A : Fleur ronde à 4 pétales dans un cercle d'or
        ctx.strokeStyle = goldColor;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(cx, cy, 24, 0, Math.PI * 2);
        ctx.stroke();

        ctx.fillStyle = goldColor;
        for (let a = 0; a < 4; a++) {
          const angle = a * (Math.PI / 2);
          const px = cx + Math.cos(angle) * 11;
          const py = cy + Math.sin(angle) * 11;
          ctx.beginPath();
          ctx.arc(px, py, 7.5, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.beginPath();
        ctx.arc(cx, cy, 3.5, 0, Math.PI * 2);
        ctx.fill();
      } else if (type === 1) {
        // Motif B : Étoile florale effilée à 4 branches
        ctx.fillStyle = goldColor;
        ctx.beginPath();
        for (let a = 0; a < 4; a++) {
          const angle = a * (Math.PI / 2);
          const tipX = cx + Math.cos(angle) * 26;
          const tipY = cy + Math.sin(angle) * 26;
          const c1x = cx + Math.cos(angle - Math.PI / 4) * 6;
          const c1y = cy + Math.sin(angle - Math.PI / 4) * 6;
          const c2x = cx + Math.cos(angle + Math.PI / 4) * 6;
          const c2y = cy + Math.sin(angle + Math.PI / 4) * 6;
          if (a === 0) ctx.moveTo(c1x, c1y);
          ctx.quadraticCurveTo(cx, cy, tipX, tipY);
          ctx.quadraticCurveTo(cx, cy, c2x, c2y);
        }
        ctx.fill();

        // Cœur négatif
        ctx.fillStyle = darkBrown;
        ctx.beginPath();
        ctx.arc(cx, cy, 4, 0, Math.PI * 2);
        ctx.fill();
      } else if (type === 2) {
        // Motif C : Losange diamant avec étoile intérieure
        ctx.fillStyle = goldColor;
        ctx.beginPath();
        ctx.moveTo(cx, cy - 25);
        ctx.lineTo(cx + 21, cy);
        ctx.lineTo(cx, cy + 25);
        ctx.lineTo(cx - 21, cy);
        ctx.closePath();
        ctx.fill();

        // Étoile négative découpée au centre
        ctx.fillStyle = darkBrown;
        for (let a = 0; a < 4; a++) {
          const angle = a * (Math.PI / 2);
          const tx = cx + Math.cos(angle) * 11;
          const ty = cy + Math.sin(angle) * 11;
          ctx.beginPath();
          ctx.arc(tx, ty, 3.8, 0, Math.PI * 2);
          ctx.fill();
        }
      } else {
        // Motif D : Monogramme entrelacé stylisé LV
        ctx.strokeStyle = goldOutline;
        ctx.lineWidth = 4;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        // Lettre L
        ctx.beginPath();
        ctx.moveTo(cx - 10, cy - 14);
        ctx.lineTo(cx - 10, cy + 12);
        ctx.lineTo(cx + 4, cy + 12);
        ctx.stroke();

        // Lettre V croisée
        ctx.beginPath();
        ctx.moveTo(cx - 5, cy - 8);
        ctx.lineTo(cx + 4, cy + 11);
        ctx.lineTo(cx + 14, cy - 12);
        ctx.stroke();
      }
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(3, 2);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 8;
  lvTextureCache.monogram = texture;
  return texture;
}

function getTaurillonLeatherTexture(): THREE.CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  if (lvTextureCache.taurillon) return lvTextureCache.taurillon;

  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.fillStyle = '#161618';
  ctx.fillRect(0, 0, 256, 256);

  // Micro-relief de cuir pleine fleur Taurillon
  for (let y = 0; y < 256; y += 4) {
    for (let x = 0; x < 256; x += 4) {
      const jx = (Math.random() - 0.5) * 2;
      const jy = (Math.random() - 0.5) * 2;
      const r = 1.2 + Math.random() * 0.8;
      const shade = 18 + Math.floor(Math.random() * 14);
      ctx.fillStyle = `rgb(${shade}, ${shade}, ${shade + 2})`;
      ctx.beginPath();
      ctx.arc(x + 2 + jx, y + 2 + jy, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(4, 4);
  texture.colorSpace = THREE.SRGBColorSpace;
  lvTextureCache.taurillon = texture;
  return texture;
}

function getCalacattaMarbleTexture(): THREE.CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  if (lvTextureCache.marble) return lvTextureCache.marble;

  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Base blanc pur Calacatta
  ctx.fillStyle = '#f8fafc';
  ctx.fillRect(0, 0, 512, 512);

  // Veinures douces de marbre gris perle
  ctx.strokeStyle = 'rgba(203, 213, 225, 0.45)';
  ctx.lineWidth = 14;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(0, i * 110 + 20);
    ctx.bezierCurveTo(160, i * 90 + 30, 310, i * 120 + 10, 512, i * 100 + 40);
    ctx.stroke();
  }

  // Fines veinures nettes grises et or champagne
  ctx.strokeStyle = 'rgba(148, 163, 184, 0.55)';
  ctx.lineWidth = 2.5;
  for (let i = 0; i < 7; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 75, 0);
    ctx.bezierCurveTo(i * 65 + 35, 170, i * 85 - 25, 330, i * 75 + 40, 512);
    ctx.stroke();
  }

  ctx.strokeStyle = 'rgba(217, 180, 74, 0.4)';
  ctx.lineWidth = 1.8;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(40 + i * 120, 0);
    ctx.bezierCurveTo(110 + i * 95, 190, 30 + i * 105, 360, 80 + i * 120, 512);
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  lvTextureCache.marble = texture;
  return texture;
}

function getBakedCookieTexture(): THREE.CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  if (lvTextureCache.bakedCookie) return lvTextureCache.bakedCookie;

  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // 1. Fond pâte sablée dorée avec gradient radial de cuisson Maillard
  const grad = ctx.createRadialGradient(256, 256, 40, 256, 256, 256);
  grad.addColorStop(0, '#eab368');    // Cœur moelleux doré
  grad.addColorStop(0.65, '#cb8538'); // Zone de caramélisation intermédiaire
  grad.addColorStop(1, '#8c4715');    // Bordure croustillante bien dorée / brunie
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 512, 512);

  // 2. Grain sablé et micro-porosité
  const imgData = ctx.getImageData(0, 0, 512, 512);
  for (let i = 0; i < imgData.data.length; i += 4) {
    const noise = (Math.random() - 0.5) * 22;
    imgData.data[i] = Math.max(0, Math.min(255, imgData.data[i] + noise));
    imgData.data[i + 1] = Math.max(0, Math.min(255, imgData.data[i + 1] + noise * 0.8));
    imgData.data[i + 2] = Math.max(0, Math.min(255, imgData.data[i + 2] + noise * 0.5));
  }
  ctx.putImageData(imgData, 0, 0);

  // 3. Fissures et craquelures de cuisson naturelles
  ctx.strokeStyle = 'rgba(110, 48, 12, 0.75)';
  ctx.lineCap = 'round';
  for (let c = 0; c < 18; c++) {
    const startAngle = Math.random() * Math.PI * 2;
    const startR = 60 + Math.random() * 120;
    let cx = 256 + Math.cos(startAngle) * startR;
    let cy = 256 + Math.sin(startAngle) * startR;

    ctx.lineWidth = 1.2 + Math.random() * 2.2;
    ctx.beginPath();
    ctx.moveTo(cx, cy);

    const steps = 3 + Math.floor(Math.random() * 4);
    for (let s = 0; s < steps; s++) {
      cx += (Math.random() - 0.5) * 36;
      cy += (Math.random() - 0.5) * 36;
      ctx.lineTo(cx, cy);
    }
    ctx.stroke();
  }

  // 4. Morceaux de chocolat noir fondus Valrhona incrustés
  for (let ch = 0; ch < 14; ch++) {
    const angle = Math.random() * Math.PI * 2;
    const dist = 30 + Math.random() * 170;
    const chX = 256 + Math.cos(angle) * dist;
    const chY = 256 + Math.sin(angle) * dist;
    const size = 12 + Math.random() * 18;

    ctx.fillStyle = '#1c0d06';
    ctx.beginPath();
    ctx.ellipse(chX, chY, size, size * (0.6 + Math.random() * 0.4), Math.random() * Math.PI, 0, Math.PI * 2);
    ctx.fill();

    // Reflet lustré brillant du chocolat chaud
    ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
    ctx.beginPath();
    ctx.ellipse(chX - size * 0.25, chY - size * 0.2, size * 0.3, size * 0.18, -0.4, 0, Math.PI * 2);
    ctx.fill();
  }

  // 5. Pépites de fleur de sel scintillantes
  ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
  for (let s = 0; s < 40; s++) {
    const sx = Math.random() * 512;
    const sy = Math.random() * 512;
    ctx.fillRect(sx, sy, 2 + Math.random() * 2, 2 + Math.random() * 2);
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  lvTextureCache.bakedCookie = texture;
  return texture;
}

function getCarbonFiberTexture(): THREE.CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  if (lvTextureCache.carbonFiber) return lvTextureCache.carbonFiber;

  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.fillStyle = '#111215';
  ctx.fillRect(0, 0, 128, 128);

  const cellSize = 16;
  for (let y = 0; y < 128; y += cellSize) {
    for (let x = 0; x < 128; x += cellSize) {
      const isAlt = ((x / cellSize) + (y / cellSize)) % 2 === 0;
      ctx.fillStyle = isAlt ? '#1d1e24' : '#141518';
      ctx.fillRect(x, y, cellSize, cellSize);

      // Micro-tissage directionnel
      ctx.strokeStyle = isAlt ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.35)';
      ctx.lineWidth = 1;
      for (let l = 0; l < cellSize; l += 3) {
        ctx.beginPath();
        if (isAlt) {
          ctx.moveTo(x + l, y);
          ctx.lineTo(x + l, y + cellSize);
        } else {
          ctx.moveTo(x, y + l);
          ctx.lineTo(x + cellSize, y + l);
        }
        ctx.stroke();
      }
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(8, 8);
  texture.colorSpace = THREE.SRGBColorSpace;
  lvTextureCache.carbonFiber = texture;
  return texture;
}

function getParchmentPaperTexture(): THREE.CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  if (lvTextureCache.parchmentPaper) return lvTextureCache.parchmentPaper;

  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.fillStyle = '#f8efd8';
  ctx.fillRect(0, 0, 256, 256);

  // Plis et texture fibreuse de cuisson
  ctx.strokeStyle = 'rgba(212, 186, 142, 0.35)';
  ctx.lineWidth = 1.5;
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.moveTo(0, Math.random() * 256);
    ctx.bezierCurveTo(80, Math.random() * 256, 180, Math.random() * 256, 256, Math.random() * 256);
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(2, 2);
  texture.colorSpace = THREE.SRGBColorSpace;
  lvTextureCache.parchmentPaper = texture;
  return texture;
}

