const SupercarDynamicTelemetry: React.FC<{
  isStarted: boolean;
  isTrackSim: boolean;
  chassisRef: React.RefObject<THREE.Group | null>;
  wheelSpinRefs: React.MutableRefObject<(THREE.Group | null)[]>;
  aeroStreamRef: React.RefObject<THREE.Group | null>;
}> = ({ isStarted, isTrackSim, chassisRef, wheelSpinRefs, aeroStreamRef }) => {
  useFrame((state, delta) => {
    const t = state.clock.getElapsedTime();
    if (chassisRef.current) {
      if (isTrackSim) {
        chassisRef.current.position.y = 0.008 + Math.sin(t * 28) * 0.0022;
        chassisRef.current.rotation.x = 0.012 + Math.sin(t * 6) * 0.004;
      } else if (isStarted) {
        chassisRef.current.position.y = 0.02 + Math.sin(t * 42) * 0.0014;
        chassisRef.current.rotation.x = 0;
      } else {
        chassisRef.current.position.y = 0.02;
        chassisRef.current.rotation.x = 0;
      }
    }
    const spinSpeed = isTrackSim ? 26 : isStarted ? 3.5 : 0;
    if (spinSpeed > 0) {
      for (let i = 0; i < 4; i++) {
        const w = wheelSpinRefs.current[i];
        if (w) {
          w.rotation.y -= delta * spinSpeed;
        }
      }
    }
    if (aeroStreamRef.current && isTrackSim) {
      aeroStreamRef.current.position.z = -((t * 3.2) % 1.4) + 0.7;
    }
  });
  return null;
};

export const VictoriaVRSupercar: React.FC<{ entity?: EntitySpec; isSelected?: boolean; isHovered?: boolean }> = ({ entity, isSelected, isHovered }) => {
  const carbonTexture = useMemo(() => getCarbonFiberTexture(), []);
  const flags = useWorldStore(s => s.world.flags || {});
  const isConfigured = Boolean(flags['supercar_configured']);
  const isStarted = Boolean(flags['supercar_started']);
  const isTrackSim = Boolean(flags['supercar_track_sim']);
  const customPaint = useWorldStore(s => s.supercarCustomPaint);
  const chassisRef = useRef<THREE.Group | null>(null);
  const wheelSpinRefs = useRef<(THREE.Group | null)[]>([null, null, null, null]);
  const aeroStreamRef = useRef<THREE.Group | null>(null);

  const brakeCalipers = useWorldStore(s => s.supercarBrakeCalipers) || 'gold';
  const carbonPackActive = useWorldStore(s => s.supercarCarbonPack ?? true);
  const caliperColor = brakeCalipers === 'red' ? '#ef4444' : brakeCalipers === 'cyan' ? '#38bdf8' : '#facc15';

  // Dynamic finish with high luminance & clearcoat PBR paint (respects both configurator customPaint and entity.visuals.color from change_color rules)
  const entityPaint = entity?.visuals?.color && entity.visuals.color.toLowerCase() !== '#ef4444' && entity.visuals.color.toLowerCase() !== '#e11d48'
    ? entity.visuals.color
    : null;
  const activePaint = customPaint || entityPaint;
  const bodyPaint = activePaint || (isConfigured ? '#dc2626' : (isHovered ? '#f43f5e' : (entity?.visuals?.color || '#ef4444')));
  const accentPaint = activePaint ? activePaint : (isConfigured ? '#991b1b' : '#b91c1c');

  return (
    <group position={[0, 0.36, 0]}>
      <SupercarDynamicTelemetry
        isStarted={isStarted}
        isTrackSim={isTrackSim}
        chassisRef={chassisRef}
        wheelSpinRefs={wheelSpinRefs}
        aeroStreamRef={aeroStreamRef}
      />
      {/* 1. Châssis Central Aérodynamique Profilé (Monocoque Carbone & Carrosserie Galbée) */}
      <group ref={chassisRef} position={[0, 0.02, 0]}>
        {/* Coque ventrale basse profilée */}
        <RoundedBox args={[1.74, 0.28, 4.22]} radius={0.08} smoothness={8} position={[0, -0.04, 0]} castShadow receiveShadow>
          <meshPhysicalMaterial
            color={bodyPaint}
            metalness={0.45}
            roughness={0.14}
            clearcoat={1.0}
            clearcoatRoughness={0.04}
            reflectivity={0.95}
          />
        </RoundedBox>

        {/* Capot avant plongeant aérodynamique (Wedge profile) */}
        <mesh position={[0, 0.08, 1.25]} rotation={[-0.16, 0, 0]} castShadow receiveShadow>
          <boxGeometry args={[1.42, 0.14, 1.48]} />
          <meshPhysicalMaterial
            color={bodyPaint}
            metalness={0.45}
            roughness={0.14}
            clearcoat={1.0}
            clearcoatRoughness={0.04}
          />
        </mesh>

        {/* Nez plongeant en biseau avec calandre d'aspiration */}
        <mesh position={[0, -0.06, 2.05]} rotation={[-0.24, 0, 0]} castShadow>
          <boxGeometry args={[1.34, 0.16, 0.36]} />
          <meshPhysicalMaterial color={accentPaint} metalness={0.5} roughness={0.16} clearcoat={1.0} />
        </mesh>

        {/* Double extracteur d'air NACA sur le capot avant */}
        {[-0.32, 0.32].map((nx, ni) => (
          <mesh key={ni} position={[nx, 0.16, 1.15]} rotation={[-0.16, 0, 0]}>
            <boxGeometry args={[0.16, 0.02, 0.42]} />
            <meshStandardMaterial
              map={carbonTexture || undefined}
              color={carbonTexture ? '#ffffff' : '#0f172a'}
              roughness={0.35}
            />
          </mesh>
        ))}

        {/* Capot moteur arrière fastback profilé avec ouïes de ventilation thermique */}
        <mesh position={[0, 0.14, -1.18]} rotation={[0.14, 0, 0]} castShadow receiveShadow>
          <boxGeometry args={[1.38, 0.16, 1.62]} />
          <meshPhysicalMaterial
            color={bodyPaint}
            metalness={0.45}
            roughness={0.14}
            clearcoat={1.0}
            clearcoatRoughness={0.04}
          />
        </mesh>
        {/* Lamelles d'aération moteur en carbone (Louvers V12) */}
        {[-0.65, -0.95, -1.25, -1.55].map((lz, li) => (
          <mesh key={li} position={[0, 0.23, lz]} rotation={[0.22, 0, 0]}>
            <boxGeometry args={[0.82, 0.015, 0.12]} />
            <meshStandardMaterial
              map={carbonTexture || undefined}
              color={carbonTexture ? '#ffffff' : '#18181b'}
              roughness={0.3}
            />
          </mesh>
        ))}
      </group>

      {/* 2. Ailes Galbées Avant et Arrière (Muscular Sculpted Wheel Arches) */}
      {/* Ailes Avant Galbées */}
      {[-0.82, 0.82].map((fx, fi) => (
        <group key={`front-fender-${fi}`} position={[fx, 0.06, 1.28]}>
          <RoundedBox args={[0.26, 0.32, 1.12]} radius={0.08} smoothness={6} castShadow receiveShadow>
            <meshPhysicalMaterial color={bodyPaint} metalness={0.45} roughness={0.14} clearcoat={1.0} clearcoatRoughness={0.04} />
          </RoundedBox>
        </group>
      ))}

      {/* Ailes Arrière Élargies Hypercar */}
      {[-0.84, 0.84].map((rx, ri) => (
        <group key={`rear-fender-${ri}`} position={[rx, 0.08, -1.28]}>
          <RoundedBox args={[0.30, 0.36, 1.24]} radius={0.09} smoothness={6} castShadow receiveShadow>
            <meshPhysicalMaterial color={bodyPaint} metalness={0.45} roughness={0.14} clearcoat={1.0} clearcoatRoughness={0.04} />
          </RoundedBox>
          {/* Écope latérale de refroidissement freins & V12 */}
          <mesh position={[rx < 0 ? 0.08 : -0.08, 0.02, 0.58]} rotation={[0, rx < 0 ? -0.25 : 0.25, 0]}>
            <boxGeometry args={[0.16, 0.22, 0.38]} />
            <meshStandardMaterial
              map={carbonTexture || undefined}
              color={carbonTexture ? '#ffffff' : '#0f172a'}
              roughness={0.3}
            />
          </mesh>
        </group>
      ))}

      {/* 3. Cockpit Bulle Hypercar en verre fumé saphir & Intérieur Sport Alcantara */}
      <group position={[0, 0.34, -0.18]}>
        {/* Verrière aérodynamique galbée en verre fumé avec réfraction */}
        <RoundedBox args={[1.24, 0.38, 1.82]} radius={0.16} smoothness={8} castShadow>
          <meshPhysicalMaterial
            color="#090d16"
            transmission={0.82}
            transparent
            opacity={0.92}
            roughness={0.04}
            clearcoat={1.0}
            clearcoatRoughness={0.02}
            ior={1.52}
          />
        </RoundedBox>

        {/* Montants de pare-brise et arche de toit en carbone */}
        <mesh position={[0, 0.16, -0.05]}>
          <boxGeometry args={[1.18, 0.04, 1.45]} />
          <meshStandardMaterial
            map={carbonTexture || undefined}
            color={carbonTexture ? '#ffffff' : '#1e293b'}
            roughness={0.3}
          />
        </mesh>

        {/* Intérieur : Deux Sièges Baquets Sport en Alcantara / Carbone */}
        {[-0.28, 0.28].map((sx, si) => (
          <group key={si} position={[sx, -0.08, -0.15]}>
            {/* Assise baquet */}
            <RoundedBox args={[0.34, 0.10, 0.42]} radius={0.02} smoothness={3}>
              <meshStandardMaterial color="#0f172a" roughness={0.8} />
            </RoundedBox>
            {/* Dossier baquet incliné avec renforts latéraux */}
            <mesh position={[0, 0.18, -0.18]} rotation={[-0.22, 0, 0]}>
              <boxGeometry args={[0.32, 0.36, 0.08]} />
              <meshStandardMaterial color="#1e293b" roughness={0.7} />
            </mesh>
            {/* Appuie-tête baquet avec liseré contrasté */}
            <mesh position={[0, 0.36, -0.22]}>
              <boxGeometry args={[0.18, 0.12, 0.06]} />
              <meshStandardMaterial color={accentPaint} roughness={0.6} />
            </mesh>
          </group>
        ))}

        {/* Tableau de bord numérique holographique & Cockpit virtuel */}
        <mesh position={[0, -0.02, 0.42]} rotation={[-0.32, 0, 0]}>
          <planeGeometry args={[0.48, 0.14]} />
          <meshStandardMaterial
            color="#0ea5e9"
            emissive={isStarted ? '#38bdf8' : '#0284c7'}
            emissiveIntensity={isStarted ? 2.5 : 1.2}
          />
        </mesh>

        {/* Volant Sport à méplat inspiré Formule 1 */}
        <group position={[-0.28, -0.04, 0.32]} rotation={[0.35, 0, 0]}>
          <mesh>
            <torusGeometry args={[0.11, 0.015, 12, 28]} />
            <meshStandardMaterial color="#18181b" roughness={0.5} metalness={0.5} />
          </mesh>
          {/* Moyeu central avec logo */}
          <mesh position={[0, 0, 0]}>
            <cylinderGeometry args={[0.035, 0.035, 0.02, 16]} />
            <meshStandardMaterial color="#38bdf8" metalness={0.9} roughness={0.2} />
          </mesh>
        </group>
      </group>

      {/* 4. Lame Aérodynamique Avant (Splitter Carbone) & Ailettes Vortex */}
      <group position={[0, -0.14, 2.14]}>
        <mesh castShadow>
          <boxGeometry args={[1.94, 0.04, 0.36]} />
          <meshStandardMaterial
            map={carbonTexture || undefined}
            color={carbonTexture ? '#ffffff' : '#1e293b'}
            roughness={0.25}
            metalness={0.4}
          />
        </mesh>
        {/* Ailettes Vortex latérales */}
        {[-0.96, 0.96].map((wx, wi) => (
          <mesh key={wi} position={[wx, 0.08, 0]}>
            <boxGeometry args={[0.03, 0.18, 0.32]} />
            <meshStandardMaterial color="#18181b" roughness={0.3} metalness={0.5} />
          </mesh>
        ))}
      </group>

      {/* 5. Bas de Caisse Latéraux Sculptés & Lames Aéro */}
      {[-0.94, 0.94].map((px, pi) => (
        <group key={pi} position={[px, -0.10, 0]}>
          <mesh castShadow>
            <boxGeometry args={[0.10, 0.05, 2.05]} />
            <meshStandardMaterial
              map={carbonTexture || undefined}
              color={carbonTexture ? '#ffffff' : '#18181b'}
              roughness={0.3}
              metalness={0.4}
            />
          </mesh>
        </group>
      ))}

      {/* 6. Aileron Arrière Actif GT sur Doubles Mâts Col-de-Cygne */}
      {carbonPackActive && (
        <group position={[0, 0.52, -1.98]}>
          {/* Profil d'aile en fibre de carbone à profil porteur inversé */}
          <mesh castShadow>
            <boxGeometry args={[1.90, 0.035, 0.38]} />
            <meshStandardMaterial
              map={carbonTexture || undefined}
              color={carbonTexture ? '#ffffff' : '#1e293b'}
              roughness={0.25}
              metalness={0.4}
            />
          </mesh>
          {/* Flasques d'extrémité aérodynamiques (Endplates profilées) */}
          {[-0.94, 0.94].map((ex, ei) => (
            <mesh key={ei} position={[ex, 0.05, 0]}>
              <boxGeometry args={[0.02, 0.18, 0.44]} />
              <meshStandardMaterial color="#0f172a" roughness={0.3} />
            </mesh>
          ))}
          {/* Mâts profilés en aluminium aéronautique usiné (Swan-neck mounts) */}
          {[-0.52, 0.52].map((sx, si) => (
            <mesh key={si} position={[sx, -0.22, 0.02]} rotation={[-0.15, 0, 0]}>
              <boxGeometry args={[0.035, 0.42, 0.09]} />
              <meshStandardMaterial color="#334155" metalness={0.9} roughness={0.2} />
            </mesh>
          ))}
        </group>
      )}

      {/* 7. Diffuseur Arrière Aérodynamique & Sorties d'Échappement Titanium V12 */}
      <group position={[0, -0.16, -2.08]}>
        <mesh>
          <boxGeometry args={[1.88, 0.08, 0.36]} />
          <meshStandardMaterial
            map={carbonTexture || undefined}
            color={carbonTexture ? '#ffffff' : '#1e293b'}
            roughness={0.3}
          />
        </mesh>
        {/* 4 Canaux d'extraction ventrale d'effet de sol */}
        {[-0.54, -0.22, 0.22, 0.54].map((dx, di) => (
          <mesh key={di} position={[dx, -0.03, 0]}>
            <boxGeometry args={[0.02, 0.14, 0.38]} />
            <meshStandardMaterial color="#090d16" roughness={0.4} />
          </mesh>
        ))}
        {/* 4 Embouts d'échappement Titanium bleuté anodisé */}
        {[-0.15, -0.05, 0.05, 0.15].map((ex, ei) => (
          <mesh key={ei} position={[ex, 0.08, 0.12]} rotation={[Math.PI / 2, 0, 0]}>
            <cylinderGeometry args={[0.038, 0.038, 0.14, 20, 1, true]} />
            <meshStandardMaterial
              color="#60a5fa"
              metalness={0.95}
              roughness={0.12}
              emissive={isStarted ? '#3b82f6' : '#000000'}
              emissiveIntensity={isStarted ? 1.5 : 0}
            />
          </mesh>
        ))}
      </group>

      {/* 8. Les 4 Roues Forgées 20" Diamantées, Disques Carbone-Céramique Ventilés & Étriers Brembo Racing */}
      {[
        [-0.96, -0.06, 1.28],
        [0.96, -0.06, 1.28],
        [-0.96, -0.06, -1.28],
        [0.96, -0.06, -1.28]
      ].map(([wx, wy, wz], wi) => (
        <group key={wi} position={[wx, wy, wz]} rotation={[0, 0, Math.PI / 2]}>
          <group ref={el => { wheelSpinRefs.current[wi] = el; }}>
            {/* Pneu taille basse rainuré sport */}
            <mesh castShadow>
              <cylinderGeometry args={[0.33, 0.33, 0.24, 32]} />
              <meshStandardMaterial color="#09090b" roughness={0.85} />
            </mesh>
            {/* Jante forgée diamantée argent satiné (high contrast) */}
            <mesh position={[0, 0, 0]}>
              <cylinderGeometry args={[0.245, 0.245, 0.245, 24]} />
              <meshStandardMaterial color="#e2e8f0" metalness={0.94} roughness={0.14} />
            </mesh>
            {/* Bâtons de jante directionnels profilés */}
            {[0, 1, 2, 3, 4, 5].map(si => (
              <mesh key={si} rotation={[0, (si * Math.PI) / 3, 0]}>
                <boxGeometry args={[0.025, 0.246, 0.44]} />
                <meshStandardMaterial color="#cbd5e1" metalness={0.95} roughness={0.10} />
              </mesh>
            ))}
            {/* Disque de frein carbone-céramique ventilé percé */}
            <mesh position={[0, 0.02, 0]}>
              <cylinderGeometry args={[0.18, 0.18, 0.02, 24]} />
              <meshStandardMaterial color="#475569" metalness={0.88} roughness={0.35} />
            </mesh>
          </group>
          {/* Étrier de frein sport Brembo personnalisable (fixe sur le porte-moyeu) */}
          <mesh position={[0.08, 0.10, 0]}>
            <boxGeometry args={[0.10, 0.05, 0.06]} />
            <meshStandardMaterial color={caliperColor} metalness={0.8} roughness={0.18} />
          </mesh>
        </group>
      ))}

      {/* Flux aérodynamique laminaire en soufflerie lors de la simulation sur piste */}
      {isTrackSim && (
        <group ref={aeroStreamRef} position={[0, 0.42, 0]}>
          {[-0.48, 0, 0.48].map((ax, ai) => (
            <mesh key={ai} position={[ax, ai === 1 ? 0.16 : 0.04, 0]}>
              <boxGeometry args={[0.018, 0.012, 3.6]} />
              <meshBasicMaterial color="#38bdf8" transparent opacity={0.65} />
            </mesh>
          ))}
        </group>
      )}

      {/* 9. Signature Lumineuse : Phares Matrix LED Laser (avec wrapper <mesh> valide) & Bandeau Arrière OLED */}
      {/* Phares avant Matrix LED Blanc Glacier & Cyan Laser */}
      {[-0.66, 0.66].map((hx, hi) => (
        <group key={hi} position={[hx, 0.09, 2.06]} rotation={[-0.18, hx < 0 ? 0.12 : -0.12, 0]}>
          {/* Boîtier lentille de phare */}
          <mesh>
            <planeGeometry args={[0.34, 0.07]} />
            <meshStandardMaterial
              color="#e0f2fe"
              emissive="#38bdf8"
              emissiveIntensity={4.0}
              roughness={0.1}
            />
          </mesh>
          {/* Projecteur laser directionnel */}
          <pointLight position={[0, 0, 0.35]} color="#38bdf8" intensity={isStarted ? 6.0 : 3.0} distance={7} />
        </group>
      ))}

      {/* Bandeau continu arrière OLED Rouge Intense Luminescent */}
      <mesh position={[0, 0.14, -2.07]}>
        <boxGeometry args={[1.74, 0.035, 0.02]} />
        <meshStandardMaterial color="#ef4444" emissive="#ff1111" emissiveIntensity={3.6} />
      </mesh>

      {/* Halo de sélection VIP Showroom au sol */}
      {(isSelected || isHovered) && (
        <mesh position={[0, -0.32, 0]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[2.1, 2.35, 48]} />
          <meshBasicMaterial color="#38bdf8" transparent opacity={0.75} />
        </mesh>
      )}
    </group>
  );
};

