// ============================================================================
// ⚪ MODÈLES 3D JEU DE GO (GOBAN EN BOIS DE KAYA, PIERRES & BOLS GOKE)
// ============================================================================

const TraditionalGobanBoard: React.FC<{ isSelected?: boolean; isHovered?: boolean }> = ({ isSelected = false, isHovered = false }) => {
  const lineCount = 9;
  const gridSpan = 0.82;
  const step = gridSpan / (lineCount - 1);
  const lines = Array.from({ length: lineCount }, (_, i) => -gridSpan / 2 + i * step);

  const hoshiCoords = [
    [-gridSpan / 2 + 2 * step, -gridSpan / 2 + 2 * step],
    [-gridSpan / 2 + 2 * step, -gridSpan / 2 + 6 * step],
    [-gridSpan / 2 + 6 * step, -gridSpan / 2 + 2 * step],
    [-gridSpan / 2 + 6 * step, -gridSpan / 2 + 6 * step],
    [0, 0]
  ];

  return (
    <group position={[0, 0, 0]}>
      {/* 1. Bloc massif de Goban en bois de Kaya précieux */}
      <mesh position={[0, 0.06, 0]} castShadow receiveShadow>
        <boxGeometry args={[1.05, 0.12, 1.05]} />
        <meshStandardMaterial color="#d49b52" roughness={0.42} metalness={0.06} />
      </mesh>

      {/* 2. Pieds traditionnels sculptés en forme de gardénia (4 coins) */}
      {[[-0.42, -0.42], [0.42, -0.42], [-0.42, 0.42], [0.42, 0.42]].map(([fx, fz], idx) => (
        <group key={idx} position={[fx, -0.015, fz]}>
          <mesh castShadow>
            <cylinderGeometry args={[0.045, 0.032, 0.05, 16]} />
            <meshStandardMaterial color="#b47834" roughness={0.5} metalness={0.08} />
          </mesh>
        </group>
      ))}

      {/* 3. Lignes de la grille 9x9 (lignes noires laquées de 2.5mm gravées au sommet) */}
      <group position={[0, 0.121, 0]}>
        {lines.map((zPos, idx) => (
          <mesh key={`h_${idx}`} position={[0, 0, zPos]}>
            <planeGeometry args={[gridSpan, 0.003]} />
            <meshBasicMaterial color="#1e293b" side={THREE.DoubleSide} />
          </mesh>
        ))}
        {lines.map((xPos, idx) => (
          <mesh key={`v_${idx}`} position={[xPos, 0, 0]} rotation={[0, Math.PI / 2, 0]}>
            <planeGeometry args={[gridSpan, 0.003]} />
            <meshBasicMaterial color="#1e293b" side={THREE.DoubleSide} />
          </mesh>
        ))}

        {/* 4. Points étoiles (Hoshi) et point central (Tengen) */}
        {hoshiCoords.map(([hx, hz], idx) => (
          <mesh key={`hoshi_${idx}`} position={[hx, 0.001, hz]} rotation={[-Math.PI / 2, 0, 0]}>
            <circleGeometry args={[0.008, 16]} />
            <meshBasicMaterial color="#0f172a" />
          </mesh>
        ))}
      </group>

      {/* Halo de sélection / survol */}
      {(isSelected || isHovered) && (
        <mesh position={[0, 0.06, 0]}>
          <boxGeometry args={[1.08, 0.13, 1.08]} />
          <meshBasicMaterial color={isSelected ? '#fbbf24' : '#38bdf8'} wireframe transparent opacity={0.5} />
        </mesh>
      )}
    </group>
  );
};

const TraditionalGoStone: React.FC<{ entity: EntitySpec; isSelected?: boolean; isHovered?: boolean }> = ({ entity, isSelected = false, isHovered = false }) => {
  const name = (entity.name || '').toLowerCase();
  const isBlack = name.includes('noir') || entity.id.toLowerCase().includes('black') || entity.visuals?.color === '#18181b';

  return (
    <group position={[0, 0, 0]}>
      {/* Pierre de Go biconvexe traditionnelle (forme lenticulaire profilée) */}
      <mesh castShadow receiveShadow>
        <cylinderGeometry args={[0.038, 0.038, 0.016, 24]} />
        <meshStandardMaterial
          color={isBlack ? '#111827' : '#f8fafc'}
          roughness={isBlack ? 0.18 : 0.12}
          metalness={isBlack ? 0.35 : 0.05}
        />
      </mesh>
      {/* Dôme supérieur bombé biconvexe */}
      <mesh position={[0, 0.008, 0]} castShadow>
        <sphereGeometry args={[0.041, 24, 12, 0, Math.PI * 2, 0, Math.PI / 3.2]} />
        <meshStandardMaterial
          color={isBlack ? '#111827' : '#ffffff'}
          roughness={isBlack ? 0.15 : 0.1}
          metalness={isBlack ? 0.35 : 0.05}
        />
      </mesh>
      {/* Dôme inférieur bombé biconvexe */}
      <mesh position={[0, -0.008, 0]} rotation={[Math.PI, 0, 0]}>
        <sphereGeometry args={[0.041, 24, 12, 0, Math.PI * 2, 0, Math.PI / 3.2]} />
        <meshStandardMaterial
          color={isBlack ? '#111827' : '#ffffff'}
          roughness={isBlack ? 0.18 : 0.12}
          metalness={isBlack ? 0.35 : 0.05}
        />
      </mesh>

      {/* Anneau subtil de sélection / survol */}
      {(isSelected || isHovered) && (
        <mesh position={[0, 0.012, 0]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.042, 0.048, 24]} />
          <meshBasicMaterial color={isSelected ? '#fbbf24' : '#38bdf8'} side={THREE.DoubleSide} />
        </mesh>
      )}
    </group>
  );
};

const TraditionalGokeBowl: React.FC<{ entity: EntitySpec; isSelected?: boolean; isHovered?: boolean }> = ({ entity, isSelected = false, isHovered = false }) => {
  const name = (entity.name || '').toLowerCase();
  const isBlackBowl = name.includes('noir') || entity.id.toLowerCase().includes('black');

  return (
    <group position={[0, 0, 0]}>
      {/* Corps du bol en bois tourné (châtaignier / noyer foncé) */}
      <mesh position={[0, 0.05, 0]} castShadow receiveShadow>
        <cylinderGeometry args={[0.11, 0.08, 0.10, 24]} />
        <meshStandardMaterial color={isBlackBowl ? '#2d1810' : '#4a2818'} roughness={0.5} metalness={0.08} />
      </mesh>
      {/* Rebord courbé supérieur */}
      <mesh position={[0, 0.102, 0]}>
        <torusGeometry args={[0.098, 0.012, 12, 24]} />
        <meshStandardMaterial color={isBlackBowl ? '#24120a' : '#3d2012'} roughness={0.55} />
      </mesh>
      {/* Pierres empilées à l'intérieur du bol */}
      {Array.from({ length: 7 }, (_, i) => {
        const ang = (i / 7) * Math.PI * 2;
        const rad = i === 0 ? 0 : 0.045;
        const stoneColor = isBlackBowl ? '#111827' : '#f8fafc';
        return (
          <mesh key={i} position={[Math.cos(ang) * rad, 0.088 + (i % 2) * 0.006, Math.sin(ang) * rad]} castShadow>
            <sphereGeometry args={[0.032, 16, 10]} />
            <meshStandardMaterial color={stoneColor} roughness={0.2} metalness={isBlackBowl ? 0.3 : 0.05} />
          </mesh>
        );
      })}

      {(isSelected || isHovered) && (
        <mesh position={[0, 0.005, 0]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.115, 0.125, 24]} />
          <meshBasicMaterial color={isSelected ? '#fbbf24' : '#38bdf8'} side={THREE.DoubleSide} />
        </mesh>
      )}
    </group>
  );
};

